function PricesChartPage() {
  const { state, patch } = useDecision();
  const { t, lang } = useTranslate();

  const [fullscreen, setFullscreen] =
    useState(false);

  const [historyLimit, setHistoryLimit] =
    useState(250);

  const [activeIndicators, setActiveIndicators] =
    useState({
      rsi: true,
      macd: true,
      obv: false,
      cci: false
    });

  useEffect(() => {
    setHistoryLimit(250);
  }, [state.symbol, state.timeframe]);

  const quality =
    useQuality(state.symbol, state.timeframe, state.mode);

  const candles =
    useChartCandles(
      state.symbol,
      state.timeframe,
      historyLimit
    );

  if (
    quality.status === "loading" ||
    candles.status === "loading"
  ) {
    return <EmptyState type="loading"/>;
  }

  if (quality.status === "error") {
    return (
      <EmptyState
        type="error"
        onRetry={quality.retry}
      />
    );
  }

  if (candles.status === "error") {
    return (
      <EmptyState
        type="error"
        onRetry={candles.retry}
      />
    );
  }

  const q = quality.value;

  const levels = {
    activation:
      q.scenario.activation,
    arrival:
      q.scenario.arrival,
    review:
      q.scenario.review,
    invalidation:
      q.scenario.invalidation
  };

  const nmp = q.nmp.level;

  const range =
    nmp === null
      ? []
      : [
          nmp * 0.998,
          nmp * 1.002
        ];

  const last =
    candles.value.at(-1);

  const toggleIndicator = (id) => {
    setActiveIndicators(
      (current) => ({
        ...current,
        [id]: !current[id]
      })
    );
  };

  const nextHistoryLimit =
    CHART_HISTORY_LIMITS.find(
      (value) =>
        value >
        historyLimit
    );

  const sourceReturnedLess =
    candles.value.length <
    historyLimit;

  const levelLegend = (
    <div className="chart-level-legend">
      {[
        ["activation", levels.activation],
        ["arrival", levels.arrival],
        ["review", levels.review],
        ["invalidation", levels.invalidation]
      ].map(([key, value]) => (
        <div
          className="chart-level-legend-item"
          key={key}
        >
          <i className={`l-${key}`}/>
          <span>{t(key)}</span>
          <b>
            {formatNumber(
              value,
              lang,
              4
            )}
          </b>
        </div>
      ))}

      <div className="chart-level-legend-item nmp-legend-item">
        <i className="l-nmp"/>
        <span>{t("nmpZone")}</span>
        <b>
          {formatNumber(
            nmp,
            lang,
            4
          )}
        </b>
      </div>
    </div>
  );

  const chart = (
    <CandleChart
      key={
        `${state.symbol}-${state.timeframe}-${historyLimit}`
      }
      candles={candles.value}
      levels={levels}
      nmpRange={range}
      nmpLevel={nmp}
      lang={lang}
      t={t}
      activeIndicators={
        activeIndicators
      }
      contextKey={
        `${state.symbol}-${state.timeframe}-${historyLimit}`
      }
      legend={levelLegend}
    />
  );

  return (
    <div className="prices-chart-page">
      <PageHeader
        title={t("chartTitle")}
        subtitle={
          `${assetName(
            findAsset(state.symbol),
            lang
          )} · ${state.symbol}`
        }
        actions={
          <div className="inline-actions">
            <button
              className="button secondary"
              onClick={() => {
                quality.retry();
                candles.retry();
              }}
            >
              <Icon name="refresh"/>
              {t("refresh")}
            </button>

            <button
              className="button secondary"
              onClick={() =>
                setFullscreen(true)
              }
            >
              <Icon name="fullscreen"/>
              {t("fullscreen")}
            </button>
          </div>
        }
      />

      <ModeContractContext
        q={q}
        requestedMode={state.mode}
        lang={lang}
      />

      <Card
        title={
          `${assetName(
            findAsset(state.symbol),
            lang
          )} · ${state.timeframe}`
        }
        actions={
          <DataMeta
            updatedAt={q.generatedAt}
          />
        }
      >
        <div className="chart-toolbar">
          <select
            value={state.symbol}
            onChange={(event) => {
              const asset =
                findAsset(
                  event.target.value
                );

              patch({
                market: asset.market,
                symbol: asset.symbol
              });
            }}
          >
            {ASSETS.map(
              (asset) => (
                <option
                  value={asset.symbol}
                  key={asset.symbol}
                >
                  {assetName(
                    asset,
                    lang
                  )} · {asset.symbol}
                </option>
              )
            )}
          </select>

          <div className="segmented chart-timeframes">
            {TIMEFRAMES.map(
              (timeframe) => (
                <button
                  type="button"
                  className={
                    state.timeframe ===
                    timeframe
                      ? "active"
                      : ""
                  }
                  onClick={() =>
                    patch({
                      timeframe
                    })
                  }
                  key={timeframe}
                >
                  {timeframe}
                </button>
              )
            )}
          </div>
        </div>

        <div className="chart-source-controls">
          <label>
            <span>
              {CHART_COPY[lang].history}
            </span>

            <select
              value={historyLimit}
              onChange={(event) =>
                setHistoryLimit(
                  Number(
                    event.target.value
                  )
                )
              }
            >
              {CHART_HISTORY_LIMITS.map(
                (value) => (
                  <option
                    value={value}
                    key={value}
                  >
                    {value}
                  </option>
                )
              )}
            </select>
          </label>

          <div className="chart-source-status">
            <strong>
              {candles.value.length}
            </strong>
            <span>
              {CHART_COPY[lang].loadedCandles}
            </span>
            <small>
              {candles.endpoint || "—"}
            </small>
          </div>

          <button
            type="button"
            className="button secondary"
            disabled={
              !nextHistoryLimit ||
              sourceReturnedLess
            }
            onClick={() => {
              if (nextHistoryLimit) {
                setHistoryLimit(
                  nextHistoryLimit
                );
              }
            }}
          >
            {CHART_COPY[lang].loadMore}
          </button>
        </div>

        <p className="chart-source-note">
          {sourceReturnedLess
            ? CHART_COPY[lang]
                .allAvailableLoaded
            : CHART_COPY[lang]
                .sourceLimit}
        </p>

        <div className="technical-toolbox">
          <strong>
            {CHART_COPY[lang].technicalTools}
          </strong>

          <div className="technical-tool-buttons">
            {CHART_INDICATORS.map(
              (indicator) => (
                <button
                  type="button"
                  key={indicator.id}
                  className={
                    activeIndicators[
                      indicator.id
                    ]
                      ? "active"
                      : ""
                  }
                  aria-pressed={
                    activeIndicators[
                      indicator.id
                    ]
                  }
                  onClick={() =>
                    toggleIndicator(
                      indicator.id
                    )
                  }
                >
                  {indicator.label}
                </button>
              )
            )}
          </div>
        </div>

        <div className="ohlc-row">
          <Metric
            label={t("open")}
            value={formatNumber(
              last?.open,
              lang,
              5
            )}
          />

          <Metric
            label={t("highPrice")}
            value={formatNumber(
              last?.high,
              lang,
              5
            )}
          />

          <Metric
            label={t("lowPrice")}
            value={formatNumber(
              last?.low,
              lang,
              5
            )}
          />

          <Metric
            label={t("closePrice")}
            value={formatNumber(
              last?.close,
              lang,
              5
            )}
            tone={
              last &&
              last.close >=
              last.open
                ? "success"
                : "danger"
            }
          />
        </div>

        {chart}
      </Card>

      <Card title={t("divergence")}>
        <div className="divergence-box">
          <Badge tone="muted">
            {q.raw?.cross_timeframe_divergence
              ? t("partial")
              : t("noDivergence")}
          </Badge>

          <p>
            {state.view === "professional"
              ? (
                  lang === "ar"
                    ? "يتم التحقق من الانحراف المنتظم والخفي على الإطار المختار دون نسخ نتائج إطار آخر."
                    : "Regular and hidden divergence are checked on the selected timeframe without copying another timeframe."
                )
              : t("noDivergence")}
          </p>
        </div>
      </Card>

      {fullscreen
        ? (
            <div className="modal-layer">
              <button
                className="modal-backdrop"
                onClick={() =>
                  setFullscreen(false)
                }
              />

              <div className="modal fullscreen-modal">
                <div className="modal-head">
                  <h2>
                    {t("chartTitle")}
                  </h2>

                  <button
                    className="icon-button"
                    onClick={() =>
                      setFullscreen(false)
                    }
                  >
                    <Icon name="close"/>
                  </button>
                </div>

                <div className="modal-body fullscreen-chart">
                  {chart}
                </div>
              </div>
            </div>
          )
        : null}
    </div>
  );
}
