function SupportPage() {
  const { state } = useDecision();
  const { t, lang } = useTranslate();

  const draftKey =
    "ndsp.commercial.support.draft.v1";

  const savedDraft =
    readJsonStorage(
      draftKey,
      {}
    );

  const [form, setForm] = useState({
    category:
      savedDraft.category ||
      "technical",
    subject:
      savedDraft.subject ||
      "",
    message:
      savedDraft.message ||
      "",
    email:
      savedDraft.email ||
      ""
  });

  const [submitState, setSubmitState] =
    useState({
      status: "idle",
      message: "",
      reference: ""
    });

  useEffect(() => {
    localStorage.setItem(
      draftKey,
      JSON.stringify(form)
    );
  }, [form]);

  const patchForm = (patch) => {
    setForm((current) => ({
      ...current,
      ...patch
    }));
  };

  const submit = async (event) => {
    event.preventDefault();

    if (
      !form.subject.trim() ||
      !form.message.trim()
    ) {
      setSubmitState({
        status: "error",
        message:
          lang === "ar"
            ? "اكتب عنوان الطلب وتفاصيله قبل الإرسال."
            : "Enter the request subject and details before submitting.",
        reference: ""
      });
      return;
    }

    setSubmitState({
      status: "loading",
      message:
        lang === "ar"
          ? "جارٍ إرسال الطلب…"
          : "Submitting request…",
      reference: ""
    });

    try {
      const result =
        await submitSupportTicket({
          ...form,
          symbol: state.symbol,
          market: state.market,
          timeframe: state.timeframe,
          readingType: state.mode,
          viewLevel: state.view,
          lang: state.lang,
          page:
            window.location.pathname,
          createdAt:
            new Date().toISOString()
        });

      const reference =
        result?.body?.ticket_id ||
        result?.body?.id ||
        result?.body?.reference ||
        "";

      setSubmitState({
        status: "success",
        message:
          lang === "ar"
            ? "تم استلام طلب الدعم بنجاح."
            : "The support request was received successfully.",
        reference:
          reference
            ? String(reference)
            : ""
      });

      setForm((current) => ({
        ...current,
        subject: "",
        message: ""
      }));
    } catch (error) {
      setSubmitState({
        status: "error",
        message:
          lang === "ar"
            ? "واجهة الدعم جاهزة، لكن خدمة استقبال التذاكر الخلفية غير متاحة حاليًا. تم الاحتفاظ بالمسودة على هذا الجهاز."
            : "The support interface is ready, but the backend ticket service is currently unavailable. The draft remains saved on this device.",
        reference: ""
      });
    }
  };

  return (
    <>
      <PageHeader
        title={t("support")}
        subtitle={
          lang === "ar"
            ? "إرسال طلب دعم مرتبط بسياق القراءة الحالية"
            : "Submit a support request linked to the current reading context"
        }
      />

      <div className="content-grid two support-grid">
        <Card
          title={
            lang === "ar"
              ? "طلب دعم جديد"
              : "New support request"
          }
        >
          <form
            className="support-form"
            onSubmit={submit}
          >
            <label>
              <span>
                {
                  lang === "ar"
                    ? "نوع الطلب"
                    : "Request type"
                }
              </span>

              <select
                value={form.category}
                onChange={(event) =>
                  patchForm({
                    category:
                      event.target.value
                  })
                }
              >
                <option value="technical">
                  {
                    lang === "ar"
                      ? "مشكلة تقنية"
                      : "Technical issue"
                  }
                </option>

                <option value="account">
                  {
                    lang === "ar"
                      ? "الحساب والاشتراك"
                      : "Account and subscription"
                  }
                </option>

                <option value="data">
                  {
                    lang === "ar"
                      ? "بيانات وقراءات"
                      : "Data and readings"
                  }
                </option>

                <option value="other">
                  {
                    lang === "ar"
                      ? "أخرى"
                      : "Other"
                  }
                </option>
              </select>
            </label>

            <label>
              <span>
                {
                  lang === "ar"
                    ? "البريد للتواصل"
                    : "Contact email"
                }
              </span>

              <input
                type="email"
                value={form.email}
                onChange={(event) =>
                  patchForm({
                    email:
                      event.target.value
                  })
                }
                placeholder="name@example.com"
              />
            </label>

            <label>
              <span>
                {
                  lang === "ar"
                    ? "عنوان الطلب"
                    : "Subject"
                }
              </span>

              <input
                type="text"
                value={form.subject}
                onChange={(event) =>
                  patchForm({
                    subject:
                      event.target.value
                  })
                }
              />
            </label>

            <label>
              <span>
                {
                  lang === "ar"
                    ? "التفاصيل"
                    : "Details"
                }
              </span>

              <textarea
                rows="7"
                value={form.message}
                onChange={(event) =>
                  patchForm({
                    message:
                      event.target.value
                  })
                }
              />
            </label>

            <button
              className="button primary"
              type="submit"
              disabled={
                submitState.status ===
                "loading"
              }
            >
              {
                submitState.status ===
                "loading"
                  ? (
                      lang === "ar"
                        ? "جارٍ الإرسال…"
                        : "Submitting…"
                    )
                  : (
                      lang === "ar"
                        ? "إرسال الطلب"
                        : "Submit request"
                    )
              }
            </button>
          </form>

          {
            submitState.status !== "idle"
              ? (
                  <div
                    className={
                      `support-result ${
                        submitState.status
                      }`
                    }
                  >
                    <strong>
                      {submitState.message}
                    </strong>

                    {
                      submitState.reference
                        ? (
                            <small>
                              {
                                lang === "ar"
                                  ? "المرجع"
                                  : "Reference"
                              }
                              :{" "}
                              {
                                submitState.reference
                              }
                            </small>
                          )
                        : null
                    }
                  </div>
                )
              : null
          }
        </Card>

        <Card
          title={
            lang === "ar"
              ? "سياق الطلب"
              : "Request context"
          }
        >
          <div className="advanced-list">
            <span>
              {t("market")}
              <b>
                {marketLabel(
                  state.market,
                  lang
                )}
              </b>
            </span>

            <span>
              {t("asset")}
              <b>{state.symbol}</b>
            </span>

            <span>
              {t("timeframe")}
              <b>{state.timeframe}</b>
            </span>

            <span>
              {t("readingType")}
              <b>{t(state.mode)}</b>
            </span>
          </div>

          <div className="callout">
            <Icon name="info"/>
            <p>
              {
                lang === "ar"
                  ? "لا تظهر رسالة نجاح إلا بعد قبول الطلب من خدمة الدعم الخلفية."
                  : "A success message appears only after the backend support service accepts the request."
              }
            </p>
          </div>
        </Card>
      </div>
    </>
  );
}

